        internal new static void Dispatch(IntPtr userData, int methodId, IntPtr argv)
        {
            try
            {
                DispatchCore(userData, methodId, argv);
            }
            catch (Exception __exception)
            {
                ApiRuntime.ReportCallbackException("a virtual override", __exception);
            }
        }

        static void DispatchCore(IntPtr userData, int methodId, IntPtr argv)
        {
            var target = (QXYSeries)GCHandle.FromIntPtr(userData).Target;
            switch (methodId)
            {
                case 1: // childEvent
                {
                    target.ChildEvent(QChildEvent.FromTransientHandle(Marshal.ReadIntPtr(argv, 1 * IntPtr.Size)));
                    break;
                }
                case 2: // customEvent
                {
                    target.CustomEvent(QEvent.FromTransientHandle(Marshal.ReadIntPtr(argv, 1 * IntPtr.Size)));
                    break;
                }
                case 3: // event
                {
                    var result = target.Event(QEvent.FromTransientHandle(Marshal.ReadIntPtr(argv, 1 * IntPtr.Size)));
                    ApiRuntime.WriteResult(Marshal.ReadIntPtr(argv, 0), result);
                    break;
                }
                case 4: // eventFilter
                {
                    var result = target.EventFilter(QObject.FromHandle(Marshal.ReadIntPtr(argv, 1 * IntPtr.Size)), QEvent.FromTransientHandle(Marshal.ReadIntPtr(argv, 2 * IntPtr.Size)));
                    ApiRuntime.WriteResult(Marshal.ReadIntPtr(argv, 0), result);
                    break;
                }
                case 5: // timerEvent
                {
                    target.TimerEvent(QTimerEvent.FromTransientHandle(Marshal.ReadIntPtr(argv, 1 * IntPtr.Size)));
                    break;
                }
            }
        }

